window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/natureza_2021.js"]=[{"title":"Corrigir acidez sem acrescentar contaminante","steps":["O pH 4,3 deve aumentar até a faixa 5,5–6,5.","KOH fornece OH⁻, que neutraliza H⁺, e K⁺, nutriente em déficit.","E satisfaz simultaneamente correção do pH e compatibilidade nutricional."],"alternatives":{"A":"Ácido fosfórico aumenta a acidez, quando se deseja elevar o pH.","B":"Sulfato de cálcio repõe nutrientes, mas não é a base necessária para essa correção.","C":"O alumínio não é nutriente indicado e pode trazer toxicidade.","D":"FeCl₂ não neutraliza adequadamente a acidez e acrescenta cloreto indesejado.","E":"KOH neutraliza o excesso de acidez e fornece potássio, que estava abaixo da referência."},"takeaway":"Escolha um corretivo considerando pH e composição da solução, não apenas seu nome.","key":"natureza:N802","area":"natureza","year":2021,"number":91,"answer":"E","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A barra curta soa mais aguda, mas o som viaja no mesmo ar","steps":["Para barras semelhantes, a menor tem frequência fundamental maior.","A velocidade de propagação no ar depende do meio, não da altura musical.","Assim f₁>f₂ e v₁=v₂: alternativa D."],"alternatives":{"A":"A barra menor não tem frequência inferior, e o som não muda de velocidade por isso.","B":"A igualdade das velocidades está correta, mas a frequência foi invertida.","C":"As duas comparações contrariam o modelo de barras e de propagação no mesmo meio.","D":"A barra curta é mais aguda, e ambos os sons têm a mesma velocidade no ar.","E":"A frequência é maior, mas isso não torna o som mais veloz no mesmo meio."},"takeaway":"Não confunda frequência do emissor com velocidade de propagação da onda.","key":"natureza:N463","area":"natureza","year":2021,"number":92,"answer":"D","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A seleção preserva comportamentos que favorecem sobrevivência","steps":["O polvo apresenta variações de forma, cor e comportamento.","Mimetismos que reduzem predação podem favorecer sobrevivência e reprodução.","E explica a manutenção evolutiva dessas características por seleção natural."],"alternatives":{"A":"Todos compartilham ancestrais remotos; isso não explica o mimetismo específico.","B":"Mutações iguais às de peixes ou serpentes não são necessárias ao comportamento.","C":"Observar outros animais não explica a origem e fixação hereditária da capacidade.","D":"Semelhança de aparência não prova convergência de estruturas e funções entre essas espécies.","E":"Os comportamentos vantajosos podem ter sido favorecidos pelas pressões seletivas."},"takeaway":"Seleção natural não cria uma característica por necessidade; atua sobre variação existente.","key":"natureza:N230","area":"natureza","year":2021,"number":93,"answer":"E","subject":"Biologia","topic":"Evolução e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A trajetória deve chegar a 35 metros em 120 metros horizontais","steps":["Use y=x·tanθ−g·x²/(2v₀²cos²θ), com origem em B e x positivo em direção a A.","Para x=120, y=35, tanθ=4/3 e cos²θ=0,36: 35=160−200000/v₀².","Daí v₀²=1600 e v₀=40 m/s, opção C; a trajetória também supera a elevação intermediária."],"alternatives":{"A":"30 m/s não fornece altura suficiente para atingir A na posição indicada.","B":"35 m/s ainda dá altura inferior a 35 m quando x=120 m.","C":"40 m/s satisfaz simultaneamente alcance horizontal e desnível do alvo.","D":"45 m/s faria a bala passar acima de A mantendo o mesmo ângulo.","E":"50 m/s também ultrapassaria a altura do alvo nessa abscissa."},"takeaway":"Em lançamento entre alturas diferentes, use a equação da trajetória, não a fórmula do alcance no mesmo nível.","key":"natureza:N386","area":"natureza","year":2021,"number":94,"answer":"C","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Trinta e cinco anos correspondem a sete meias-vidas","steps":["O número de intervalos é 35/5=7.","A massa remanescente é 500·(1/2)⁷=500/128.","O resultado é 3,90625 g, aproximadamente 3,9 g: A."],"alternatives":{"A":"3,9 g é a massa que resta após sete reduções sucessivas à metade.","B":"31,2 g corresponde aproximadamente a quatro meias-vidas, apenas 20 anos.","C":"62,5 g seria o valor após três meias-vidas, ou 15 anos.","D":"125 g é o valor após duas meias-vidas, equivalentes a 10 anos.","E":"250 g é a massa após uma única meia-vida, ou 5 anos."},"takeaway":"Meia-vida descreve redução multiplicativa, não subtração constante de massa.","key":"natureza:N627","area":"natureza","year":2021,"number":95,"answer":"A","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O primeiro códon de parada encerra a proteína","steps":["A tradução começa no AUG e termina antes de um códon de parada.","Em B, CAA do códon 4 vira UAA: sobram somente três aminoácidos.","As demais alterações não introduzem uma parada anterior ao quarto códon."],"alternatives":{"A":"A deleção desloca a leitura, mas o primeiro códon alterado continua sendo UUC, não parada.","B":"CAA vira UAA no quarto códon e encerra a tradução após três aminoácidos.","C":"A alteração no sexto códon não interrompe antes do quarto.","D":"Trocar UAG por UGG retira a parada original e pode alongar a tradução.","E":"A deleção acontece no quinto códon, depois de já traduzidos os quatro primeiros."},"takeaway":"Uma mutação pontual pode encurtar mais a proteína que uma deleção: localize o primeiro stop.","key":"natureza:N110","area":"natureza","year":2021,"number":96,"answer":"B","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Óleo e base dão sabão por saponificação","steps":["Óleos vegetais contêm triacilgliceróis, que são ésteres.","A hidrólise básica com NaOH forma glicerol e sais de ácidos graxos.","Esses sais constituem o sabão: reação E, saponificação."],"alternatives":{"A":"O processo não depende de redução do estado de oxidação do óleo.","B":"Epoxidação forma anéis de três membros com oxigênio, não o sabão descrito.","C":"Substituição é uma descrição ampla e não nomeia especificamente essa hidrólise de ésteres.","D":"Esterificação forma éster; aqui o éster é consumido por hidrólise básica.","E":"Saponificação é a reação dos triésteres com base que produz os sais do sabão."},"takeaway":"Reconheça reagentes e produtos: éster + base → álcool + carboxilato.","key":"natureza:N702","area":"natureza","year":2021,"number":97,"answer":"E","subject":"Química","topic":"Reações orgânicas e polímeros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A analogia do gabarito é funcional, não anatômica","steps":["No feto, as trocas gasosas acontecem na placenta, não nos pulmões.","O forame oval e outros desvios reduzem o fluxo pulmonar; o sangue retorna da placenta ao circuito sistêmico.","D é a analogia simplificada esperada com peixes: não há passagem funcional por dois circuitos respiratório e sistêmico independentes. Isso não significa que o coração fetal tenha a anatomia de um peixe."],"alternatives":{"A":"A presença anatômica de vasos pulmonares não torna o circuito fetal igual ao de uma ave adulta.","B":"Metabolismo lento não explica a segurança fisiológica dos desvios fetais.","C":"A separação ventricular não elimina a comunicação entre átrios mencionada no enunciado.","D":"O gabarito compara o percurso funcional sem respiração pulmonar ao circuito simples dos peixes; o sistema fetal real é mais complexo e inclui desvios.","E":"A proteção não se baseia numa alternância temporal que isole inteiramente sangue arterial e venoso."},"takeaway":"Na comparação fetal, diferencie o modelo didático de circulação e a anatomia real dos mamíferos.","key":"natureza:N197","area":"natureza","year":2021,"number":98,"answer":"D","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Do Sol chega radiação; o ar quente sobe por convecção","steps":["A energia solar atravessa o espaço por ondas eletromagnéticas.","A superfície aquecida transfere energia ao ar, que sobe e modifica a circulação.","A reúne irradiação e convecção, nessa ordem."],"alternatives":{"A":"Radiação leva energia do Sol; movimento do ar aquecido caracteriza convecção.","B":"O segundo mecanismo dominante descrito envolve movimento de ar, não só radiação.","C":"Condução exige matéria em contato e não explica a transmissão pelo espaço.","D":"O primeiro processo não é convecção: não há fluxo de matéria do Sol até a cidade.","E":"O Sol não aquece a Terra por corrente convectiva através do espaço."},"takeaway":"Convecção transporta energia com matéria; radiação dispensa um meio material.","key":"natureza:N503","area":"natureza","year":2021,"number":99,"answer":"A","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A mesma folha evidencia a influência do ar","steps":["Amassar a folha praticamente não altera sua massa.","Muda a forma e a área exposta, diminuindo a importância da força de arrasto.","B explica por que o tempo de queda pode mudar no ar."],"alternatives":{"A":"O peso permanece praticamente igual na comparação da mesma folha.","B":"A resistência do ar depende da forma, área e velocidade e altera a queda.","C":"A massa não muda ao amassar a folha.","D":"A densidade não é a força comum que atua e explica diretamente os dois exemplos.","E":"A aceleração gravitacional local é a mesma; a força de arrasto é que muda."},"takeaway":"Na queda livre ideal, corpos têm a mesma aceleração; em ar, compare peso e arrasto.","key":"natureza:N387","area":"natureza","year":2021,"number":100,"answer":"B","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Converter massa em volume somente ao final","steps":["A proporção fornecida dá 50·0,50=25 kg de etanol teórico.","Com rendimento de 80%, obtêm-se 20 kg.","Como 0,80 g/mL=0,80 kg/L, V=20/0,80=25 L: C."],"alternatives":{"A":"16 resulta de multiplicar massa por densidade, em vez de dividir.","B":"20 é a massa em quilogramas, não o volume em litros.","C":"25 L inclui rendimento e conversão correta pela densidade.","D":"64 L não respeita a proporção de massa nem o rendimento fornecidos.","E":"100 L superestima a produção ao inverter fatores do processo."},"takeaway":"Use a proporção explicitamente fornecida no enunciado e aplique o rendimento antes da densidade.","key":"natureza:N680","area":"natureza","year":2021,"number":101,"answer":"C","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Duas pilhas em série e voltímetro em paralelo","steps":["Cada par Cu/Zn constitui uma pilha; o zinco de uma liga-se ao cobre da outra.","As forças eletromotrizes se somam, fornecendo 2,20 V.","O cronômetro e o voltímetro ficam entre os terminais da associação: esquema B."],"alternatives":{"A":"O voltímetro está em série e há uma única pilha representada.","B":"Duas pilhas no mesmo sentido alimentam a carga, e o voltímetro mede a tensão em paralelo.","C":"As pilhas estão em oposição, contrariando a soma das tensões observada.","D":"O esquema não representa os dois geradores eletroquímicos em série da montagem.","E":"Há quatro pilhas e o voltímetro em série, diferentes do arranjo apresentado."},"takeaway":"Voltímetro mede diferença de potencial entre dois pontos e se liga em paralelo.","key":"natureza:N768","area":"natureza","year":2021,"number":102,"answer":"B","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A titulação mede a quantidade do princípio ativo","steps":["Massa total inclui também amido e celulose.","O grupo carboxílico do ácido reage com base de concentração conhecida.","O volume gasto de NaOH permite quantificar o ácido: teste 5, alternativa E."],"alternatives":{"A":"Pesar o comprimido não separa a massa do princípio ativo da dos excipientes.","B":"A densidade global não quantifica seletivamente o ácido na mistura.","C":"Papel indicador fornece faixa de pH, não dosagem quantitativa de 40 mg.","D":"A fusão pode indicar características da amostra, mas não determina essa dosagem diretamente.","E":"A titulação permite relacionar base consumida e quantidade de ácido por estequiometria."},"takeaway":"Para dosar um componente numa mistura, escolha um procedimento quantitativo compatível com sua função química.","key":"natureza:N722","area":"natureza","year":2021,"number":103,"answer":"E","subject":"Química","topic":"Estequiometria e gases","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A biomagnificação concentra contaminantes no topo","steps":["Compostos persistentes acumulam-se nos organismos expostos.","Ao consumir muitas presas, predadores podem concentrá-los ainda mais.","Golfinhos ocupam o nível trófico mais alto entre as opções: B."],"alternatives":{"A":"Esponjas podem acumular substâncias, mas não ocupam o topo da cadeia considerada.","B":"Golfinhos recebem contaminantes das presas e apresentam maior concentração por biomagnificação.","C":"Fitoplâncton introduz contaminantes na cadeia, mas ocupa sua base.","D":"Herbívoros estão acima dos produtores, porém abaixo dos grandes predadores.","E":"Algas são produtoras e não o nível trófico de maior biomagnificação."},"takeaway":"Bioacumulação ocorre no organismo; biomagnificação é o aumento ao longo dos níveis tróficos.","key":"natureza:N015","area":"natureza","year":2021,"number":104,"answer":"B","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A carga troca o sentido da força magnética","steps":["Use F=q·v×B: a velocidade inicial aponta para dentro da página e B para a direita.","Pela regra da mão direita, a força na carga positiva aponta para baixo no desenho.","Na negativa, o sentido inverte: para cima. O par está em A."],"alternatives":{"A":"A mostra forças opostas: positiva para baixo e negativa para cima.","B":"Forças iguais em sentido ignoram que as cargas têm sinais contrários.","C":"As forças não ficam paralelas à haste e ao campo magnético.","D":"A carga positiva deveria ter força para baixo, e a negativa não pode ter força nula.","E":"Os sentidos das duas forças estão invertidos em relação a q·v×B."},"takeaway":"Na força magnética, aplique a regra à carga positiva e inverta para a negativa.","key":"natureza:N334","area":"natureza","year":2021,"number":105,"answer":"A","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O fechamento adicional de anel muda a cadeia","steps":["Compare as ligações entre átomos nas duas estruturas, não só sua orientação no papel.","A lumirrubina desenhada apresenta reorganização com formação de um ciclo adicional.","Isso caracteriza isomeria de cadeia entre as opções: C; não é simples mudança E/Z."],"alternatives":{"A":"Não se apresentam apenas imagens especulares com igual conectividade.","B":"O contraste principal não é troca de uma função orgânica por outra.","C":"A reorganização do esqueleto e sua ciclização alteram a cadeia da molécula.","D":"Não se desloca somente um substituinte mantendo o mesmo esqueleto.","E":"Uma isomerização geométrica preservaria a conectividade; o desenho mostra mudança estrutural."},"takeaway":"Mais solubilidade é consequência; a classificação do isômero exige comparar a estrutura.","key":"natureza:N681","area":"natureza","year":2021,"number":106,"answer":"C","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A mesma energia cinética é atingida em menos tempo","steps":["Compare a aceleração de zero a 100 km/h para o mesmo automóvel.","A variação de energia cinética é a mesma; a versão a álcool leva 12,9 s, menos que 13,4 s.","P média=ΔEc/Δt: o álcool apresenta maior potência média nesse intervalo, C."],"alternatives":{"A":"O tempo menor é do álcool; a gasolina não tem a maior aceleração média.","B":"Velocidade máxima não permite essa comparação de potência média no intervalo indicado.","C":"A mesma variação de energia em menor tempo significa maior taxa de transferência de energia.","D":"Ter a mesma variação de velocidade não basta: é preciso considerar o tempo.","E":"Gastar mais tempo para a mesma energia corresponde a menor potência média."},"takeaway":"Potência mede rapidez de transferência de energia, não energia ou velocidade isoladamente.","key":"natureza:N422","area":"natureza","year":2021,"number":107,"answer":"C","subject":"Física","topic":"Trabalho, energia e potência","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A densidade elimina a ambiguidade do verso","steps":["O título remete aos anéis, mas a tabela oferece critério quantitativo.","O cordel afirma densidade inferior à da água.","Somente Saturno tem densidade relativa menor que 1: 0,7, portanto D."],"alternatives":{"A":"Mercúrio tem densidade relativa 5,6, muito superior à da água.","B":"Júpiter tem densidade 1,3 e não satisfaz o verso.","C":"Urano tem densidade 1,2, ainda superior à da água.","D":"Saturno tem 0,7 e é o único da tabela que satisfaz o critério de densidade.","E":"Netuno tem densidade 1,7 e não satisfaz a condição."},"takeaway":"Quando uma pista verbal é imprecisa, procure outro dado independente que decida a identificação.","key":"natureza:N598","area":"natureza","year":2021,"number":108,"answer":"D","subject":"Física","topic":"Gravitação e astronomia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ordenar a razão comprimento por área","steps":["Com a mesma resistividade, R=ρL/A.","Calcule L/A: fio 1=34,67; fio 2=11,75; fio 3=27; fio 4=106.","Logo R₂<R₃<R₁<R₄, alternativa C."],"alternatives":{"A":"O fio 1 não tem a menor razão: 34,67 supera 11,75 e 27.","B":"O fio 2 é o menor, mas o fio 3 deve vir antes do fio 1.","C":"As quatro razões em ordem crescente são 11,75; 27; 34,67; 106.","D":"O fio 4 tem a maior resistência, e não a menor.","E":"Inverte a ordem: o fio 4 deveria encerrar a lista crescente."},"takeaway":"Comprimento e área agem em sentidos opostos na resistência elétrica.","key":"natureza:N335","area":"natureza","year":2021,"number":109,"answer":"C","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Subprodutos combustíveis surgem da fermentação","steps":["O comando destaca catabolismo de baixo rendimento energético.","Fermentação libera pouca energia e conserva energia química em produtos, como etanol.","B corresponde ao processo; não se exige que toda fermentação produza etanol."],"alternatives":{"A":"Fotossíntese produz matéria orgânica, não é o catabolismo descrito.","B":"Fermentação tem menor rendimento que respiração aeróbica e pode gerar produtos combustíveis.","C":"Quimiossíntese é autotrofia, não degradação orgânica de baixo rendimento.","D":"Respiração aeróbica apresenta maior aproveitamento energético e produtos finais mais oxidados.","E":"Fosforilação oxidativa integra a respiração e não corresponde ao processo fermentativo."},"takeaway":"Um produto orgânico parcialmente oxidado pode conservar energia aproveitável como combustível.","key":"natureza:N016","area":"natureza","year":2021,"number":110,"answer":"B","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separar na escola não garante reciclar","steps":["O plano já inclui sensibilização, capacitação e coletores.","Falta conectar os resíduos separados a quem os recolha e destine adequadamente.","B fecha a cadeia com prefeitura ou cooperativa."],"alternatives":{"A":"Campanhas externas ampliam alcance, mas não resolvem a destinação do material separado.","B":"A parceria assegura recolhimento e encaminhamento, etapa operacional ausente.","C":"Visitar locais de disposição pode educar, mas não organiza o recolhimento da escola.","D":"Divulgar a iniciativa não substitui um fluxo de coleta e destinação.","E":"Receber mais resíduos externos aumenta a demanda sem solucionar o destino."},"takeaway":"Uma ação ambiental precisa integrar educação, separação, logística e destinação.","key":"natureza:N628","area":"natureza","year":2021,"number":111,"answer":"B","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conhecer o parentesco para orientar os cruzamentos","steps":["Consanguinidade aumenta a chance de reunir alelos recessivos deletérios.","Antes de separar os animais, convém identificar vínculos e características genéticas.","Entre as técnicas propostas, mapeamento genético permite orientar manejo reprodutivo: E."],"alternatives":{"A":"Inserir genes de outra origem não é necessário para organizar cruzamentos.","B":"Terapia gênica visa tratar alterações, não identificar previamente os pares de reprodução.","C":"Vacina de DNA atua na imunização, não no controle de parentesco.","D":"Clonagem terapêutica não é uma estratégia para selecionar cruzamentos menos consanguíneos.","E":"Informações genéticas podem subsidiar a escolha de reprodutores e evitar pares próximos."},"takeaway":"Controle reprodutivo pode prevenir doenças recessivas sem modificar geneticamente os animais.","key":"natureza:N111","area":"natureza","year":2021,"number":112,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reduzir cobre é diminuir seu número de oxidação","steps":["No metal inicial, o cobre tem NOX zero.","Nas espécies intermediárias apresentadas, permanece como Cu²⁺.","A etapa V usa zinco para converter Cu²⁺ novamente em Cu: redução, E."],"alternatives":{"A":"I transforma cobre metálico em Cu²⁺, portanto é oxidação do cobre.","B":"II precipita hidróxido mantendo cobre no estado +2.","C":"III forma o óxido e preserva o NOX +2 do cobre.","D":"IV forma sulfato sem alterar o estado de oxidação do cobre.","E":"V converte Cu²⁺ em Cu⁰, mediante ganho de elétrons fornecidos pelo zinco."},"takeaway":"Mudança de composto não implica oxirredução: calcule o NOX do elemento acompanhado.","key":"natureza:N769","area":"natureza","year":2021,"number":113,"answer":"E","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O arco reflexo se integra na medula espinhal","steps":["O estímulo no tendão aciona receptores de estiramento muscular.","A informação sensitiva chega à medula e ativa neurônios motores que estendem a perna.","B é a região de integração; a resposta não precisa aguardar decisão consciente."],"alternatives":{"A":"A ponte pertence ao encéfalo e não é o centro integrador desse arco patelar.","B":"A medula espinhal integra a resposta rápida entre via sensitiva e motora.","C":"O cerebelo coordena movimentos, mas não é o centro específico desse reflexo.","D":"O hipotálamo atua principalmente na homeostase e regulação neuroendócrina.","E":"A neuro-hipófise libera hormônios, não coordena esse arco reflexo motor."},"takeaway":"Reflexo medular não significa ausência de comunicação com o cérebro; significa resposta integrada na medula.","key":"natureza:N198","area":"natureza","year":2021,"number":114,"answer":"B","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Camadas térmicas em série somam resistências","steps":["Para mesma área e espessura total, compare d/k.","Alumínio: d/20; ferro: d/8; composto: d/(2·40)+d/(2·5)=9d/80.","A resistência cresce como alumínio < composto < ferro; assim a economia diminui nessa ordem: B."],"alternatives":{"A":"O composto tem resistência 9d/80, maior que a do alumínio, 4d/80.","B":"O alumínio conduz mais; o composto equivale a k=80/9≈8,89, pouco acima do ferro.","C":"O alumínio não pode ser o menos econômico: tem a maior condutividade efetiva.","D":"O composto conduz um pouco melhor que o ferro e deve vir antes dele.","E":"O ferro tem a menor taxa de condução entre os três, não a maior."},"takeaway":"Em camadas, use soma de d/k; média aritmética das condutividades não representa a associação.","key":"natureza:N504","area":"natureza","year":2021,"number":115,"answer":"B","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O fenol doa próton à base","steps":["Brønsted–Lowry define ácido como doador de H⁺.","O composto III tem hidroxilas diretamente ligadas a anéis aromáticos, isto é, fenóis.","OH⁻ desprotona esses grupos nas condições do teste: C."],"alternatives":{"A":"O N–H de uma amida não corresponde ao grupo fenólico de acidez identificável nesse teste aquoso.","B":"O composto não apresenta as hidroxilas fenólicas que reagem com a base no ensaio.","C":"Os grupos fenólicos de III cedem H⁺ ao hidróxido, formando fenóxido e água.","D":"A sulfona apresentada não tem os grupos fenólicos do teste proposto.","E":"Os oxigênios de éteres não possuem hidrogênio de hidroxila para essa neutralização."},"takeaway":"Nem todo H ligado a heteroátomo reage da mesma forma: reconheça a função e a acidez nas condições do ensaio.","key":"natureza:N835","area":"natureza","year":2021,"number":116,"answer":"C","subject":"Química","topic":"Ligações e interações intermoleculares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Biodigestão transforma dejetos em biogás","steps":["Dejetos suínos contêm matéria orgânica biodegradável.","A decomposição anaeróbia em biodigestores gera mistura rica em metano.","Esse combustível é o biogás, B, cujo uso também reduz carga poluidora."],"alternatives":{"A":"Etanol provém usualmente de fermentação de açúcares, não é o produto típico da biodigestão de dejetos.","B":"Biogás é a mistura combustível obtida pela digestão anaeróbia da matéria orgânica.","C":"Butano não é o principal combustível produzido nesse aproveitamento de resíduos.","D":"Metanol não é o produto característico dos biodigestores descritos.","E":"Biodiesel é obtido de óleos e gorduras por processamento químico, não dessa digestão."},"takeaway":"Biogás não é metano puro: é uma mistura, com metano como componente combustível importante.","key":"natureza:N629","area":"natureza","year":2021,"number":117,"answer":"B","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O alvo aquático é a larva do mosquito","steps":["O mecanismo exige ingestão da água do criadouro.","A fase larval é aquática e se alimenta nessa água.","A lesão fatal do tubo digestivo impede seu desenvolvimento: D."],"alternatives":{"A":"O adulto não vive ingerindo a água do criadouro nessa fase aquática.","B":"O ovo não ingere a substância com água, como exige o mecanismo.","C":"A morte larval é anterior e mais específica que interferir diretamente na metamorfose.","D":"A larva ingere o composto, sofre dano intestinal e não completa o desenvolvimento.","E":"Não se descreve afastamento do mosquito, e sim efeito letal após ingestão."},"takeaway":"Localize a fase do ciclo de vida que apresenta o comportamento exigido pelo controle proposto.","key":"natureza:N273","area":"natureza","year":2021,"number":118,"answer":"D","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A madeira mais resistente é rica em cerne","steps":["Cerne é a região interna do xilema, com células inativas e substâncias que podem aumentar resistência à degradação.","A espécie 1 tem cerne em grande quantidade (+++); a 5 tem apenas pequena quantidade (+).","A é a escolha mais adequada para madeira de construção, não a que tem mais casca ou floema."],"alternatives":{"A":"A espécie 1 combina grande quantidade de cerne com a resistência e durabilidade procuradas.","B":"A espécie 2 apresenta muito alburno, mas não tem cerne indicado.","C":"A espécie 3 tem floema abundante, que não substitui o cerne na madeira.","D":"A espécie 4 é rica em periderme e floema, porém não apresenta cerne.","E":"A espécie 5 possui apenas pequena quantidade de cerne, inferior à espécie 1."},"takeaway":"Madeira corresponde ao xilema; não some indiscriminadamente todos os tecidos da tabela.","key":"natureza:N252","area":"natureza","year":2021,"number":119,"answer":"A","subject":"Biologia","topic":"Botânica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A cor vista não é a faixa mais absorvida","steps":["Caroteno aparece amarelo-alaranjado porque reflete/transmite mais esses tons.","A absorção predominante deve estar na faixa complementar.","A corresponde a violeta–azul, oposta ao amarelo–laranja no esquema."],"alternatives":{"A":"Violeta e azul são complementares aos tons amarelo-alaranjados observados.","B":"Azul–verde corresponde mais diretamente ao caso avermelhado das antocianinas descritas.","C":"Absorver principalmente verde–amarelo não explica o tom amarelo-alaranjado mostrado.","D":"Amarelo–laranja é a luz percebida, não a faixa que o caroteno mais absorve.","E":"Laranja–vermelho não é a faixa complementar indicada para o caroteno."},"takeaway":"Cor de um pigmento sob luz branca está ligada ao que sobra da absorção, não ao que é absorvido.","key":"natureza:N545","area":"natureza","year":2021,"number":120,"answer":"A","subject":"Física","topic":"Óptica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A questão usa um modelo simplificado de coevolução","steps":["O texto compara menor letalidade da dengue com maior letalidade do ebola.","No modelo cobrado, menor morte do hospedeiro favorece sua manutenção e a transmissão ao longo da convivência evolutiva.","E é a inferência esperada. Ressalva: letalidade e incubação, isoladamente, não permitem datar uma relação real; evolução não exige que todo patógeno se torne menos virulento."],"alternatives":{"A":"Maior incubação não prova, por si, história evolutiva mais longa.","B":"Menor incubação também não funciona como relógio da coevolução.","C":"Matar mais hospedeiros não significa necessariamente maior sucesso de transmissão.","D":"A origem africana dos humanos não determina há quanto tempo cada vírus os infecta.","E":"No raciocínio simplificado da prova, baixa letalidade é associada à persistência do parasitismo e maior tempo de coevolução."},"takeaway":"Use a hipótese do item para identificar o gabarito, sem convertê-la numa lei universal da evolução.","key":"natureza:N299","area":"natureza","year":2021,"number":121,"answer":"E","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O repouso favorece a decantação do lodo","steps":["Decantação separa fases pela ação da gravidade.","O esquema informa maior tempo de repouso no tanque séptico, etapa 3.","Ali o material sedimentável se acumula no fundo: C."],"alternatives":{"A":"A caixa de gordura retém principalmente gordura e resíduos da cozinha, não é o tanque de sedimentação indicado.","B":"A caixa de passagem reúne fluxos, sem o tempo de repouso que caracteriza a decantação.","C":"O tanque séptico permite sedimentação e acúmulo do lodo a separar.","D":"O filtro biológico promove ação de microrganismos sobre matéria orgânica.","E":"A cisterna recebe cloro na etapa final, voltada à desinfecção."},"takeaway":"Separe funções: sedimentação, degradação biológica e desinfecção não são a mesma etapa.","key":"natureza:N630","area":"natureza","year":2021,"number":122,"answer":"C","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Auxinas favorecem enraizamento da estaca","steps":["Na estaquia, um fragmento vegetativo origina nova planta.","Para sobreviver, o caule precisa formar raízes a partir de tecido não radicular.","A aplicação basal de auxina favorece raízes adventícias: D."],"alternatives":{"A":"Floração não é o efeito necessário para estabelecer a muda por estaquia.","B":"Auxinas estão associadas também à dominância apical, não ao objetivo principal de estimular gemas laterais.","C":"Aumentar folhas não resolve a necessidade inicial de absorção da estaca.","D":"Raízes adventícias permitem fixação e absorção de água e nutrientes pela nova planta.","E":"Auxina é sinal hormonal e não fornece diretamente compostos energéticos para a muda."},"takeaway":"Adventícia é a raiz que surge em região diferente da raiz embrionária, como um caule.","key":"natureza:N253","area":"natureza","year":2021,"number":123,"answer":"D","subject":"Biologia","topic":"Botânica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cruzar três critérios seleciona a PEM","steps":["A célula deve operar com temperatura baixa, eletrólito polimérico e meio ácido.","PEM opera entre 60 e 100 °C e usa ácido poliperfluorossulfônico sólido.","C é a única que reúne todos os requisitos, não apenas um deles."],"alternatives":{"A":"AFC opera em baixa temperatura, mas usa KOH aquoso, meio básico e não membrana polimérica ácida.","B":"MSFC exige alta temperatura e carbonatos fundidos.","C":"PEM combina faixa térmica baixa, membrana polimérica e condução em meio ácido.","D":"PAFC usa ácido fosfórico líquido, não o eletrólito polimérico solicitado.","E":"SOFC opera em alta temperatura com óxido sólido, fora do perfil escolhido."},"takeaway":"Em tabelas comparativas, elimine qualquer opção que falhe em um dos critérios obrigatórios.","key":"natureza:N770","area":"natureza","year":2021,"number":124,"answer":"C","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A umidade reduz a evaporação do suor","steps":["A evaporação retira energia térmica da pele.","Com mais vapor de água no ar, há menor tendência à evaporação líquida do suor.","O resfriamento perde eficiência e aumenta o desconforto: B."],"alternatives":{"A":"Alta umidade não implica necessariamente temperatura elevada do vapor.","B":"O suor evapora com mais dificuldade e retira menos calor do corpo.","C":"Não se fornece mecanismo de maior absorção de radiação pela umidade.","D":"O fenômeno principal é transferência por evaporação, não piora decisiva da condução do ar.","E":"Com ar abaixo da temperatura corporal, condensação sobre a pele quente não explica o caso."},"takeaway":"Transpirar resfria principalmente quando o suor evapora; apenas estar molhado não basta.","key":"natureza:N505","area":"natureza","year":2021,"number":125,"answer":"B","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A chave deve selecionar um ramo por vez","steps":["No circuito D, a primeira chave em AB liga só a verde.","Em BC, ela encaminha o retorno ao ponto B da segunda chave; esta seleciona vermelha em AB ou azul em BC.","As três cores podem ser escolhidas isoladamente: D."],"alternatives":{"A":"Ao selecionar a ramificação da direita, a vermelha recebe retorno direto; ligar a azul pode acender as duas juntas.","B":"A ligação entre os pontos C não permite selecionar a vermelha isoladamente nas combinações das chaves.","C":"A azul está ligada diretamente aos terminais da bateria e fica acesa independentemente das chaves.","D":"As chaves em cascata selecionam verde ou, no segundo estágio, vermelha ou azul, sem simultaneidade.","E":"Verde e vermelha compartilham o nó A e não são selecionáveis separadamente."},"takeaway":"Em circuito comutador, siga o caminho fechado completo para cada posição das chaves.","key":"natureza:N336","area":"natureza","year":2021,"number":126,"answer":"D","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A perda de um dispersor restringe a flora","steps":["Preguiças-gigantes ingeriam frutos e sementes.","Seu deslocamento podia levar sementes a outros lugares e favorecer colonização.","A extinção reduz a dispersão, explicando menor abundância e distribuição: C."],"alternatives":{"A":"O texto não atribui o efeito a uma redução direta da produção de flores.","B":"Não se apresenta alteração no porte das plantas como mecanismo causal.","C":"A perda do animal diminui um agente de disseminação das sementes.","D":"Número de sementes por fruto não é o parâmetro alterado pela extinção descrita.","E":"Os espaços físicos não precisam desaparecer para a dispersão ficar prejudicada."},"takeaway":"Frugivoria pode prestar serviço de dispersão; perder animais pode alterar a distribuição de plantas.","key":"natureza:N017","area":"natureza","year":2021,"number":127,"answer":"C","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Energia do percurso dividida pela potência do carregador","steps":["A energia gasta é 110/5=22 kWh.","A potência ideal é U·I=220·20=4400 W=4,4 kW.","O tempo é 22/4,4=5 h: D."],"alternatives":{"A":"0,005 h resulta de dividir kWh por W sem converter a potência para kW.","B":"0,125 h não recompõe os 22 kWh com potência de 4,4 kW.","C":"2,5 h forneceria apenas 11 kWh, metade da energia utilizada.","D":"5 h a 4,4 kW repõem os 22 kWh do percurso.","E":"8 h reporiam 35,2 kWh, acima da energia necessária."},"takeaway":"km/kWh é rendimento; divida distância por rendimento para encontrar a energia.","key":"natureza:N337","area":"natureza","year":2021,"number":128,"answer":"D","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A segunda fecundação forma reserva nutritiva","steps":["Um gameta fecunda a oosfera e forma o embrião diploide.","Outro se une aos núcleos polares e forma, tipicamente, endosperma triploide.","Esse tecido nutre o embrião: B."],"alternatives":{"A":"O tecido triploide não se forma para nutrir o fruto, derivado principalmente do ovário.","B":"O endosperma é reserva utilizada no desenvolvimento do embrião e da plântula.","C":"O revestimento da semente deriva dos tegumentos do óvulo, não dessa fecundação.","D":"Não se forma um revestimento protetor do megagametófito.","E":"Vasos da planta jovem não são o tecido triploide resultante dessa união."},"takeaway":"Dupla fecundação: embrião usualmente 2n e endosperma usualmente 3n.","key":"natureza:N254","area":"natureza","year":2021,"number":129,"answer":"B","subject":"Biologia","topic":"Botânica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Acetato saturado identifica o aroma de banana","steps":["Ácido etanoico dá origem aos acetatos.","Há acetato de isoamila e acetato de benzila na tabela.","O de isoamila não tem ligação múltipla entre carbonos; o de benzila tem anel aromático. Logo banana, B."],"alternatives":{"A":"Benzoato de metila deriva do ácido benzoico, e seu anel é insaturado.","B":"Acetato de isoamila deriva do ácido etanoico e possui cadeia saturada.","C":"Acetato de benzila tem a origem ácida exigida, mas seu anel aromático torna a cadeia insaturada.","D":"Propanoato de isobutila deriva do ácido propanoico, não do etanoico.","E":"Antranilato de metila não deriva do ácido etanoico e apresenta anel aromático."},"takeaway":"Na classificação da cadeia, a carbonila C=O não conta como insaturação entre carbonos.","key":"natureza:N703","area":"natureza","year":2021,"number":130,"answer":"B","subject":"Química","topic":"Reações orgânicas e polímeros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Contar intervalos entre picos, não picos internos","steps":["A escala horizontal marca 0,2 s por divisão indicada.","Entre dois picos equivalentes consecutivos há cinco desses intervalos: T=1 s.","A frequência é 1/T=1 Hz=60 batimentos/min: B."],"alternatives":{"A":"30 batimentos/min exigiriam período de 2 s, o dobro do observado.","B":"Um ciclo por segundo corresponde a 60 ciclos em um minuto.","C":"100 batimentos/min exigiriam período de 0,6 s, diferente da separação entre picos equivalentes.","D":"120 batimentos/min corresponderiam a 0,5 s por ciclo.","E":"180 batimentos/min corresponderiam a cerca de 0,33 s por ciclo."},"takeaway":"Use dois pontos equivalentes de ciclos vizinhos: as pequenas ondas de um mesmo ciclo não são novos batimentos.","key":"natureza:N464","area":"natureza","year":2021,"number":131,"answer":"B","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pais portadores podem gerar descendente recessivo afetado","steps":["O cromossomo 10 é autossomo.","Pais não afetados podem ser heterozigotos Aa.","Aa×Aa produz 1/4 aa, afetado: herança recessiva, A."],"alternatives":{"A":"O padrão de portadores saudáveis e risco de 25% é compatível com recessividade autossômica.","B":"No modelo dominante simples, o heterozigoto portador manifestaria a condição.","C":"Codominância manifesta os dois alelos no heterozigoto, não o portador saudável descrito.","D":"A descrição identifica um gene, não combinação de muitos genes com esse padrão.","E":"Vários alelos na população não explicam o risco mendeliano e a ausência de sintomas dos portadores."},"takeaway":"Portador saudável, em herança recessiva simples, é o heterozigoto.","key":"natureza:N112","area":"natureza","year":2021,"number":132,"answer":"A","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A tensão da pilha é diferença entre potenciais de redução","steps":["Iodo se reduz a I⁻; lítio metálico se oxida.","E°=0,54−(−3,05)=3,59 V por pilha.","Três em série fornecem 10,77 V, dentro de 10,5–10,9 V do carrinho IV: D."],"alternatives":{"A":"Relógio requer aproximadamente uma pilha de 1,2–1,5 V, muito abaixo da associação.","B":"Celular corresponde à faixa próxima de uma pilha de 3,59 V, não três.","C":"A câmera exige 7,5–7,8 V, abaixo dos 10,77 V disponíveis.","D":"10,77 V está na faixa do carrinho de controle remoto, 10,5–10,9 V.","E":"Notebook exige cerca de 20 V, acima do fornecido por três pilhas."},"takeaway":"Em série somam-se as tensões; ao calcular a pilha, não some dois potenciais de redução com seus sinais originais.","key":"natureza:N338","area":"natureza","year":2021,"number":133,"answer":"D","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A temperatura altera volume e flutuabilidade","steps":["O alcoolômetro depende da densidade e do empuxo.","A elevação de temperatura dilata os materiais, alterando volumes e densidades.","A calibração a 20 °C precisa ser corrigida: C, sem pressupor reação química."],"alternatives":{"A":"Dissociação da água não explica a variação da leitura desse densímetro.","B":"A dilatação tende a reduzir, não aumentar, a densidade dos líquidos.","C":"A mudança física de volume altera a densidade e a posição de flutuação.","D":"Não é necessário mudar a composição de álcool para a leitura variar com temperatura.","E":"O fenômeno é físico, não transformação química da mistura."},"takeaway":"Instrumentos baseados em densidade exigem atenção à temperatura de calibração.","key":"natureza:N748","area":"natureza","year":2021,"number":134,"answer":"C","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conjugação exige alternância contínua na cadeia principal","steps":["Ligações π conjugadas permitem deslocalização eletrônica.","É preciso alternar ligações simples e duplas ao longo do esqueleto, não só numa ramificação.","D representa essa sequência conjugada; as outras estruturas têm interrupções ou duplas fora do padrão."],"alternatives":{"A":"O anel aromático é lateral; a cadeia principal do polímero não é conjugada.","B":"As carbonilas estão separadas por trechos saturados e não formam conjugação contínua.","C":"As duplas isoladas são separadas por mais de uma ligação simples na cadeia.","D":"A unidade repetida mantém a alternância de ligações simples e duplas no esqueleto.","E":"A cadeia apresenta carbonos saturados e o grupo éster lateral não cria conjugação contínua."},"takeaway":"Ter alguma dupla ligação não basta: a continuidade da conjugação é o critério do enunciado.","key":"natureza:N704","area":"natureza","year":2021,"number":135,"answer":"D","subject":"Química","topic":"Reações orgânicas e polímeros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
